import React from "react";
import "./Css.css";


const Css = () => {
    return (
        <>
            <div className="css-page">

                {/* Header */}
                <header className="css-header">
                    <div className="css-tag">CSS CHEAT SHEET</div>
                    <h1>CSS Complete Cheat Sheet</h1>
                    <p>
                        HTML elements ko beautiful, responsive aur interactive
                        banane ke liye CSS ka quick reference.
                    </p>
                </header>

                {/* 1. CSS Syntax */}
                <section className="css-section">
                    <h2>01. CSS Syntax</h2>

                    <div className="code-box">
                        <pre>{`selector {
    property: value;
}`}</pre>
                    </div>

                    <div className="example-box">
                        <h3>Example</h3>
                        <pre>{`p {
    color: blue;
    font-size: 20px;
}`}</pre>
                    </div>
                </section>

                {/* 2. Selectors */}
                <section className="css-section">
                    <h2>02. CSS Selectors</h2>

                    <div className="selector-grid">
                        <div className="selector-card">
                            <span>*</span>
                            <h3>Universal Selector</h3>
                            <code>*</code>
                            <p>Sabhi HTML elements ko select karta hai.</p>
                        </div>

                        <div className="selector-card">
                            <span>p</span>
                            <h3>Element Selector</h3>
                            <code>p</code>
                            <p>Specific HTML element ko select karta hai.</p>
                        </div>

                        <div className="selector-card">
                            <span>.</span>
                            <h3>Class Selector</h3>
                            <code>.box</code>
                            <p>Class ke through element select karta hai.</p>
                        </div>

                        <div className="selector-card">
                            <span>#</span>
                            <h3>ID Selector</h3>
                            <code>#header</code>
                            <p>ID ke through element select karta hai.</p>
                        </div>
                    </div>
                </section>

                {/* 3. Colors */}
                <section className="css-section">
                    <h2>03. Colors</h2>

                    <pre>{`color: red;
color: #ff0000;
color: rgb(255, 0, 0);
color: rgba(255, 0, 0, 0.5);

background-color: black;`}</pre>
                </section>

                {/* 4. Text */}
                <section className="css-section">
                    <h2>04. Text Properties</h2>

                    <div className="property-grid">
                        <div>
                            <code>color</code>
                            <p>Text ka color</p>
                        </div>

                        <div>
                            <code>font-size</code>
                            <p>Text ka size</p>
                        </div>

                        <div>
                            <code>font-family</code>
                            <p>Font ka type</p>
                        </div>

                        <div>
                            <code>font-weight</code>
                            <p>Text thickness</p>
                        </div>

                        <div>
                            <code>text-align</code>
                            <p>Text alignment</p>
                        </div>

                        <div>
                            <code>text-decoration</code>
                            <p>Underline etc.</p>
                        </div>

                        <div>
                            <code>text-transform</code>
                            <p>Uppercase / lowercase</p>
                        </div>

                        <div>
                            <code>line-height</code>
                            <p>Lines ke beech gap</p>
                        </div>
                    </div>

                    <pre>{`color: #222;
font-size: 20px;
font-family: Arial;
font-weight: bold;

text-align: center;
text-decoration: underline;
text-transform: uppercase;
line-height: 1.5;`}</pre>
                </section>

                {/* 5. Box Model */}
                <section className="css-section">
                    <h2>05. CSS Box Model</h2>

                    <div className="box-model">
                        <div className="margin-box">
                            <span>Margin</span>

                            <div className="border-box">
                                <span>Border</span>

                                <div className="padding-box">
                                    <span>Padding</span>

                                    <div className="content-box">
                                        Content
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <pre>{`width: 200px;
height: 100px;

margin: 20px;
padding: 20px;

border: 2px solid black;
box-sizing: border-box;`}</pre>
                </section>

                {/* 6. Background */}
                <section className="css-section">
                    <h2>06. Background</h2>

                    <pre>{`background-color: lightblue;

background-image: url("image.jpg");
background-size: cover;
background-position: center;
background-repeat: no-repeat;`}</pre>
                </section>

                {/* 7. Border */}
                <section className="css-section">
                    <h2>07. Border</h2>

                    <pre>{`border: 2px solid black;
border-radius: 10px;

border-top: 2px solid red;
border-right: 2px solid blue;
border-bottom: 2px solid green;
border-left: 2px solid orange;`}</pre>
                </section>

                {/* 8. Flexbox */}
                <section className="css-section">
                    <h2>08. Flexbox</h2>

                    <pre>{`display: flex;

flex-direction: row;
justify-content: center;
align-items: center;

gap: 20px;
flex-wrap: wrap;`}</pre>

                    <div className="flex-demo">
                        <div>1</div>
                        <div>2</div>
                        <div>3</div>
                        <div>4</div>
                    </div>
                </section>

                {/* 9. Grid */}
                <section className="css-section">
                    <h2>09. CSS Grid</h2>

                    <pre>{`display: grid;

grid-template-columns: repeat(3, 1fr);
gap: 20px;`}</pre>

                    <div className="grid-demo">
                        <div>1</div>
                        <div>2</div>
                        <div>3</div>
                        <div>4</div>
                        <div>5</div>
                        <div>6</div>
                    </div>
                </section>

                {/* 10. Position */}
                <section className="css-section">
                    <h2>10. Position</h2>

                    <pre>{`position: static;
position: relative;
position: absolute;
position: fixed;
position: sticky;

top: 0;
right: 0;
bottom: 0;
left: 0;`}</pre>
                </section>

                {/* 11. Display */}
                <section className="css-section">
                    <h2>11. Display</h2>

                    <pre>{`display: block;
display: inline;
display: inline-block;
display: flex;
display: grid;
display: none;`}</pre>
                </section>

                {/* 12. Width Height */}
                <section className="css-section">
                    <h2>12. Width & Height</h2>

                    <pre>{`width: 100%;
max-width: 1200px;
min-width: 300px;

height: 200px;
min-height: 100vh;
max-height: 500px;`}</pre>
                </section>

                {/* 13. Shadow */}
                <section className="css-section">
                    <h2>13. Shadow</h2>

                    <pre>{`box-shadow: 0 5px 20px rgba(0, 0, 0, 0.2);

text-shadow: 2px 2px 5px gray;`}</pre>
                </section>

                {/* 14. Transform */}
                <section className="css-section">
                    <h2>14. Transform</h2>

                    <pre>{`transform: translateX(20px);
transform: translateY(20px);
transform: scale(1.2);
transform: rotate(45deg);`}</pre>
                </section>

                {/* 15. Transition */}
                <section className="css-section">
                    <h2>15. Transition</h2>

                    <pre>{`transition: all 0.3s ease;

button:hover {
    transform: scale(1.05);
}`}</pre>
                </section>

                {/* 16. Pseudo Classes */}
                <section className="css-section">
                    <h2>16. Pseudo Classes</h2>

                    <div className="pseudo-grid">
                        <span>:hover</span>
                        <span>:focus</span>
                        <span>:active</span>
                        <span>:first-child</span>
                        <span>:last-child</span>
                        <span>:nth-child()</span>
                    </div>
                </section>

                {/* 17. Overflow */}
                <section className="css-section">
                    <h2>17. Overflow</h2>

                    <pre>{`overflow: visible;
overflow: hidden;
overflow: scroll;
overflow: auto;

overflow-x: hidden;
overflow-y: auto;`}</pre>
                </section>

                {/* 18. Z Index */}
                <section className="css-section">
                    <h2>18. Z-Index</h2>

                    <pre>{`position: relative;
z-index: 10;`}</pre>

                    <p className="simple-text">
                        <code>z-index</code> elements ki layering control karta hai.
                    </p>
                </section>

                {/* 19. Responsive */}
                <section className="css-section">
                    <h2>19. Media Query</h2>

                    <pre>{`@media (max-width: 768px) {

    .container {
        width: 100%;
    }

    h1 {
        font-size: 28px;
    }
}`}</pre>
                </section>

                {/* 20. Important Properties */}
                <section className="css-section">
                    <h2>20. Most Used CSS Properties</h2>

                    <div className="important-grid">
                        <code>margin</code>
                        <code>padding</code>
                        <code>width</code>
                        <code>height</code>
                        <code>display</code>
                        <code>position</code>
                        <code>color</code>
                        <code>background</code>
                        <code>font-size</code>
                        <code>font-weight</code>
                        <code>border</code>
                        <code>border-radius</code>
                        <code>box-shadow</code>
                        <code>opacity</code>
                        <code>cursor</code>
                        <code>z-index</code>
                    </div>
                </section>

                {/* Quick Tips */}
                <section className="css-section tips-section">
                    <h2>🚀 CSS Quick Tips</h2>

                    <p>✓ Flexbox → One-dimensional layout</p>
                    <p>✓ Grid → Two-dimensional layout</p>
                    <p>✓ Media Query → Responsive website</p>
                    <p>✓ Class → Reusable styling</p>
                    <p>✓ ID → Unique element</p>
                    <p>✓ Padding → Inside spacing</p>
                    <p>✓ Margin → Outside spacing</p>
                    <p>✓ Border → Element boundary</p>
                </section>

                <footer className="css-footer">
                    CSS Cheat Sheet • Learn • Practice • Build
                </footer>

            </div>
        </>
    );
};

export default Css;
